import { Entry } from "@napi-rs/keyring";
import {
  type Credentials,
  credentialsInput,
  ExternalMcpError,
  storedCredentials,
} from "./model.js";
export interface ClientVault {
  has(ref: string): boolean;
  get(ref: string): Credentials;
  set(ref: string, value: Credentials): void;
  remove(ref: string): void;
}
/** Service is deployment-owned; references are generated by the application. */
export function systemClientVault(service = "shuriva-external-mcp"): ClientVault {
  const entry = (ref: string) => {
    if (!/^[0-9a-f-]{36}$/.test(ref)) throw new ExternalMcpError("EXTERNAL_MCP_VAULT_REF");
    return new Entry(service, ref, { linux: { store: "secret-service" } });
  };
  return {
    has(ref) {
      try {
        const raw = entry(ref).getPassword();
        if (raw === null) return false;
        storedCredentials.parse(JSON.parse(raw));
        return true;
      } catch {
        throw new ExternalMcpError("EXTERNAL_MCP_VAULT_UNAVAILABLE", 503);
      }
    },
    get(ref) {
      try {
        const raw = entry(ref).getPassword();
        if (raw === null) return {};
        return storedCredentials.parse(JSON.parse(raw));
      } catch {
        throw new ExternalMcpError("EXTERNAL_MCP_VAULT_UNAVAILABLE", 503);
      }
    },
    set(ref, value) {
      try {
        const raw = JSON.stringify(storedCredentials.parse(value));
        if (raw.length > 32768) throw Error();
        entry(ref).setPassword(raw);
        if (entry(ref).getPassword() !== raw) throw Error();
      } catch {
        throw new ExternalMcpError("EXTERNAL_MCP_VAULT_UNAVAILABLE", 503);
      }
    },
    remove(ref) {
      try {
        entry(ref).deletePassword();
      } catch {
        throw new ExternalMcpError("EXTERNAL_MCP_VAULT_UNAVAILABLE", 503);
      }
    },
  };
}
export function validateCredentials(value: unknown) {
  return credentialsInput.parse(value);
}
